_pool: _descriptor_pool.DescriptorPool | None = None


def _resolve_dep_order() -> list[tuple[str, bytes]]:
    """Return descriptors in dependency order (dependencies before dependents)."""
    fdp_cache: dict[str, _descriptor_pb2.FileDescriptorProto] = {}
    for name, raw in _RAW_DESCRIPTORS.items():
        fdp = _descriptor_pb2.FileDescriptorProto()
        fdp.ParseFromString(raw)
        fdp_cache[fdp.name] = fdp

    # Build adjacency: file_name -> set of dependency file_names
    all_files: set[str] = set(fdp_cache.keys())
    deps: dict[str, set[str]] = {}
    for name, fdp in fdp_cache.items():
        deps[name] = {d for d in fdp.dependency if d in all_files}

    # Topological sort (Kahn's algorithm)
    in_degree: dict[str, int] = {f: 0 for f in all_files}
    dep_map: dict[str, set[str]] = defaultdict(set)
    for f, dep_set in deps.items():
        for d in dep_set:
            dep_map[d].add(f)
            in_degree[f] = in_degree.get(f, 0) + 1

    queue: deque[str] = deque(f for f, d in in_degree.items() if d == 0)
    sorted_names: list[str] = []
    while queue:
        f = queue.popleft()
        sorted_names.append(f)
        for dependent in dep_map.get(f, set()):
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)

    # Any remaining files (cycles) get appended
    remaining = all_files - set(sorted_names)
    sorted_names.extend(remaining)

    return [(name, fdp_cache[name].SerializeToString()) for name in sorted_names
            if name in _RAW_DESCRIPTORS]


def _build_pool() -> _descriptor_pool.DescriptorPool:
    """Build and return a DescriptorPool with all message types registered."""
    pool = _descriptor_pool.DescriptorPool()
    for name, raw in _resolve_dep_order():
        try:
            pool.AddSerializedFile(raw)
        except Exception as exc:
            msg = f"Failed to add {name}: {exc}"
            print(f"Warning: {msg}", file=_sys.stderr)
    return pool


def get_pool() -> _descriptor_pool.DescriptorPool:
    global _pool
    if _pool is None:
        _pool = _build_pool()
    return _pool


# ── Bootstrap: create all message classes ──────────────────────────────────
def _create_all_classes():
    """Create message classes in module scope."""
    pool = get_pool()
    mod = _sys.modules[__name__]

    all_msgs: list[tuple[str, str]] = []
    all_enums: list[tuple[str, str]] = []
    for name, raw in _RAW_DESCRIPTORS.items():
        fdp = _descriptor_pb2.FileDescriptorProto()
        fdp.ParseFromString(raw)
        pkg = fdp.package
        for msg in fdp.message_type:
            all_msgs.append((msg.name, f"{pkg}.{msg.name}"))
        for enum in fdp.enum_type:
            all_enums.append((enum.name, f"{pkg}.{enum.name}"))

    for py_name, fqn in all_msgs:
        try:
            desc = pool.FindMessageTypeByName(fqn)
            cls = _message_factory.GetMessageClass(desc)
            setattr(mod, py_name, cls)
        except KeyError:
            pass

    for py_name, fqn in all_enums:
        try:
            setattr(mod, py_name, pool.FindEnumTypeByName(fqn))
        except KeyError:
            pass

    _all = [k for k in dir(mod) if not k.startswith("_") and not k.endswith("_")]
    if _all:
        mod.__all__ = _all


_create_all_classes()


